arguments.command:
curl -s "https://api.box.com/2.0/folders/8200/items?limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for e in d['entries']:
    if e['type']=='file':
        print(e['id'], e.get('file_name',''), e.get('size'), '|', e.get('description','')[:120])
    else:
        print('FOLDER:', e['id'], e.get('name'))
"

